#pragma once//base interface for interfaces using Advise connectionstemplate < class IAdviseSink >struct IAdviseHost{    typedef IAdviseSink sink_type;    // a connection being established is identified by the callback    // interface pointer.    virtual const bool Advise  ( IAdviseSink pIAdviseSink )      =0;    // supply the callback interface pointer to this method    //to sever the connection    virtual const bool Unadvise( IAdviseSink pIAdviseSink )      =0;    // returns the sink collection iterator    //virtual IAdviseSinkIterator<IAdviseSink>* GetIterator() const =0;};